// Generate unique IDs and create vocabulary entries
let counter = 1;
const seenWords = new Set();
const formatted = [];

for (const w of rawWords) {
  const key = w[0].toLowerCase().trim();
  if (seenWords.has(key)) continue;
  seenWords.add(key);
  
  formatted.push({
    id: `voc-${String(counter).padStart(5, '0')}`,
    en: w[0],
    uz: w[1],
    phonetic: w[2],
    level: w[3],
    category: w[4],
    pos: w[5],
    example_en: w[6],
    example_uz: w[7]
  });
  counter++;
}

// Count by level
const levelCount = {};
for (const w of formatted) {
  levelCount[w.level] = (levelCount[w.level] || 0) + 1;
}

const fileContent = `// ==========================================================================
// LINGOMASTER PRO - TO'LIQ MEGA LUG'AT BAZASI
// Jami: ${formatted.length} ta so'z (A1, A2, B1, B2, C1, C2)
// A1: ${levelCount['A1']||0} | A2: ${levelCount['A2']||0} | B1: ${levelCount['B1']||0} | B2: ${levelCount['B2']||0} | C1: ${levelCount['C1']||0} | C2: ${levelCount['C2']||0}
// Har bir so'z: IPA Transkripsiya, O'zbek tarjima, Namuna gaplar
// ==========================================================================

export const VOCABULARY = ${JSON.stringify(formatted, null, 2)};

// So'zlarni darajalar bo'yicha olish
export function getWordsByLevel(level) {
  if (!level || level === 'ALL') return VOCABULARY;
  return VOCABULARY.filter(w => w.level.toUpperCase() === level.toUpperCase());
}

// So'zlarni kategoriya bo'yicha olish
export function getWordsByCategory(cat) {
  if (!cat || cat === 'ALL') return VOCABULARY;
  return VOCABULARY.filter(w => w.category === cat);
}

// Tasodifiy so'zlar tanlash
export function getRandomWords(count = 10, filterFn = null) {
  const pool = filterFn ? VOCABULARY.filter(filterFn) : [...VOCABULARY];
  const shuffled = [...pool].sort(() => 0.5 - Math.random());
  return shuffled.slice(0, Math.min(count, shuffled.length));
}

// Cheksiz generator (Endless stream)
export function* endlessWordGenerator() {
  while (true) {
    const shuffled = [...VOCABULARY].sort(() => 0.5 - Math.random());
    for (const word of shuffled) {
      yield word;
    }
  }
}
`;

const outPath = require('path').join(process.cwd(), 'js', 'data', 'vocabulary.js');
require('fs').writeFileSync(outPath, fileContent, 'utf-8');
console.log(`✅ Muvaffaqiyatli yaratildi: ${formatted.length} ta so'z`);
console.log(`📊 Darajalar bo'yicha:`, levelCount);
